// Indirect calls: the tables generated by recomp_emit (function_table.cpp) – every recompiled function by guest
// address, and every Cafe OS import by its stub address (function pointers to imports). Recompiled functions are
// looked up in a direct-mapped array over their address range (game code makes many indirect calls: vtables); the
// rest by binary search.
#include "ppc_context.h"

#include <algorithm>
#include <cstddef>
#include <memory>

extern const mh3u::ppc::FunctionEntry kFunctionTable[];
extern const size_t kFunctionCount;
extern const mh3u::ppc::FunctionEntry kImportTable[];
extern const size_t kImportCount;

namespace mh3u::ppc {
namespace {

GuestFunction find(const FunctionEntry* table, size_t count, uint32_t addr) {
    const FunctionEntry* end = table + count;
    const FunctionEntry* it =
        std::lower_bound(table, end, addr, [](const FunctionEntry& e, uint32_t a) { return e.addr < a; });
    return it != end && it->addr == addr ? it->fn : nullptr;
}

// kFunctionTable as an array indexed by (addr - lo) / 4 (functions are word aligned); built on first use.
struct DirectTable {
    uint32_t lo = 0, hi = 0;
    std::unique_ptr<GuestFunction[]> slots;
    DirectTable() {
        if (!kFunctionCount) return;
        lo = kFunctionTable[0].addr & ~3u;
        hi = kFunctionTable[kFunctionCount - 1].addr + 4;
        slots = std::make_unique<GuestFunction[]>((hi - lo) / 4);  // value-initialised: null
        for (size_t i = 0; i < kFunctionCount; ++i)
            if ((kFunctionTable[i].addr & 3) == 0) slots[(kFunctionTable[i].addr - lo) / 4] = kFunctionTable[i].fn;
    }
    GuestFunction get(uint32_t addr) const {
        if (addr < lo || addr >= hi || (addr & 3)) return nullptr;
        return slots[(addr - lo) / 4];
    }
};

const DirectTable& direct() {
    static const DirectTable t;
    return t;
}

}  // namespace

thread_local uint32_t t_indirect_target = 0;

uint32_t current_indirect_target() { return t_indirect_target; }

void call_indirect(Context& ctx, uint8_t* base, uint32_t target) {
    GuestFunction fn = direct().get(target);
    if (!fn) fn = find(kImportTable, kImportCount, target);
    if (!fn) fn = find_indirect(target);
    if (!fn) unimplemented_function(target);
    t_indirect_target = target;
    fn(ctx, base);
}

}  // namespace mh3u::ppc
